package com.lingdong.learning.student.application;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
import com.lingdong.learning.student.infrastructure.persistence.*;import com.lingdong.learning.organization.infrastructure.persistence.OrganizationMapper;import com.lingdong.learning.organization.domain.Organization;import com.lingdong.learning.datascope.application.*;import com.lingdong.learning.feature.application.FeatureAccessService;import com.lingdong.learning.common.id.IdGenerator;import com.lingdong.learning.auth.application.AuthenticatedUser;import com.lingdong.learning.auth.domain.AuthClientType;import com.lingdong.learning.student.domain.Student;import java.util.List;import java.time.Clock;
class UnassignedClassLinkTest {
 @Test void staleUnassignedCandidateCannotMoveAnExistingClass(){
  var students=mock(StudentMapper.class);var relations=mock(StudentOrganizationMapper.class);var changes=mock(StudentOrganizationChangeMapper.class);var organizations=mock(OrganizationMapper.class);var scopes=mock(OrganizationDataScopeService.class);var ids=mock(IdGenerator.class);var service=new StudentOrganizationLifecycleService(students,relations,changes,organizations,scopes,mock(FeatureAccessService.class),ids,Clock.systemUTC());var actor=new AuthenticatedUser(1L,1L,"fixture","fixture",AuthClientType.MINIAPP,List.of());var scope=mock(OrganizationDataScope.class);
  when(students.findByIdForUpdate(11L)).thenReturn(Student.create(11L,"fixture","G1",31L));when(organizations.findById(22L)).thenReturn(Organization.create(22L,21L,"21","class","class","CLASS","/21/22/",1,null));when(scopes.canAccess(1L,22L)).thenReturn(true);when(scopes.resolve(1L)).thenReturn(scope);when(relations.findActiveEnrollmentOrganizationIdsForClass(11L,22L)).thenReturn(List.of(21L));when(relations.existsActiveEnrollmentInScope(11L,21L,scope)).thenReturn(true);when(relations.findActiveClassOrganizationIdsInEnrollment(11L,21L)).thenReturn(List.of(23L));
  assertThrows(IllegalStateException.class,()->service.transferClass(actor,11L,new TransferStudentClassCommand(22L,"fixture associate",true)));verify(students).findByIdForUpdate(11L);verify(relations,never()).deactivateActiveClassesInEnrollment(anyLong(),anyLong());verify(relations,never()).activateExistingClass(anyLong(),anyLong());verifyNoInteractions(changes,ids);
 }
 @Test void legacyWebCommandsRemainTransferCompatible(){assertFalse(new TransferStudentClassCommand(22L,"legacy").requireUnassigned());assertFalse(new com.lingdong.learning.student.web.AssignStudentClassRequest(22L).requireUnassigned());}
}
